import React, { useState } from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import "./dashboard.css";

function Dashboard() {
  const [loggedIn, setLoggedIn] = useState(false);
  const [activeSection, setActiveSection] = useState("home");

  // Productos de ejemplo
  const [productos, setProductos] = useState([
    { id: 1, nombre: "Camiseta Hype", categoria: "Ropa", stock: 12 },
    { id: 2, nombre: "Gorra Urbana", categoria: "Accesorios", stock: 5 },
  ]);

  // Pedidos de ejemplo
  const [pedidos, setPedidos] = useState([
    { id: 1, cliente: "Juan", estado: "Pendiente" },
    { id: 2, cliente: "María", estado: "Enviado" },
  ]);

  const [nuevoProducto, setNuevoProducto] = useState({
    nombre: "",
    categoria: "",
    stock: "",
  });

  const [comentarios, setComentarios] = useState([
    { id: 1, usuario: "Pedro", texto: "Excelente calidad", respuesta: "" },
    { id: 2, usuario: "Lucía", texto: "Me llegó tarde", respuesta: "" },
  ]);

  // CRUD Productos
  const agregarProducto = () => {
    if (!nuevoProducto.nombre || !nuevoProducto.categoria || !nuevoProducto.stock) return;
    setProductos([
      ...productos,
      {
        id: productos.length + 1,
        ...nuevoProducto,
        stock: parseInt(nuevoProducto.stock),
      },
    ]);
    setNuevoProducto({ nombre: "", categoria: "", stock: "" });
  };

  const eliminarProducto = (id) => {
    setProductos(productos.filter((p) => p.id !== id));
  };

  const editarProducto = (id, nuevoNombre) => {
    setProductos(
      productos.map((p) =>
        p.id === id ? { ...p, nombre: nuevoNombre } : p
      )
    );
  };

  // Pedidos
  const cambiarEstadoPedido = (id, nuevoEstado) => {
    setPedidos(
      pedidos.map((p) =>
        p.id === id ? { ...p, estado: nuevoEstado } : p
      )
    );
  };

  // Comentarios
  const responderComentario = (id, respuesta) => {
    setComentarios(
      comentarios.map((c) =>
        c.id === id ? { ...c, respuesta } : c
      )
    );
  };

  // Simulación de login admin
  const loginAdmin = (e) => {
    e.preventDefault();
    setLoggedIn(true);
  };

  if (!loggedIn) {
    return (
      <div className="login-container">
        <form className="login-box" onSubmit={loginAdmin}>
          <h2>Login Admin</h2>
          <input type="text" placeholder="Usuario" required />
          <input type="password" placeholder="Contraseña" required />
          <button type="submit">Entrar</button>
        </form>
      </div>
    );
  }

  return (
    <div className="dashboard-container">
      {/* Sidebar */}
      <div className="sidebar">
        <h3>Panel Admin</h3>
        <ul>
          <li onClick={() => setActiveSection("agregar")}>Agregar producto</li>
          <li onClick={() => setActiveSection("editar")}>Editar producto</li>
          <li onClick={() => setActiveSection("eliminar")}>Eliminar producto</li>
          <li onClick={() => setActiveSection("categorias")}>Gestionar categorías</li>
          <li onClick={() => setActiveSection("pedidos")}>Ver pedidos</li>
          <li onClick={() => setActiveSection("estadopedido")}>Cambiar estado pedido</li>
          <li onClick={() => setActiveSection("inventario")}>Gestionar inventario</li>
          <li onClick={() => setActiveSection("estadisticas")}>Ver estadísticas</li>
          <li onClick={() => setActiveSection("comentarios")}>Responder comentarios</li>
        </ul>
      </div>

      {/* Contenido dinámico */}
      <div className="content">
        {activeSection === "agregar" && (
          <div>
            <h2>Agregar Producto</h2>
            <input
              type="text"
              placeholder="Nombre"
              value={nuevoProducto.nombre}
              onChange={(e) =>
                setNuevoProducto({ ...nuevoProducto, nombre: e.target.value })
              }
            />
            <input
              type="text"
              placeholder="Categoría"
              value={nuevoProducto.categoria}
              onChange={(e) =>
                setNuevoProducto({ ...nuevoProducto, categoria: e.target.value })
              }
            />
            <input
              type="number"
              placeholder="Stock"
              value={nuevoProducto.stock}
              onChange={(e) =>
                setNuevoProducto({ ...nuevoProducto, stock: e.target.value })
              }
            />
            <button onClick={agregarProducto}>Agregar</button>
          </div>
        )}

        {activeSection === "editar" && (
          <div>
            <h2>Editar Producto</h2>
            {productos.map((p) => (
              <div key={p.id}>
                <span>{p.nombre}</span>
                <input
                  type="text"
                  placeholder="Nuevo nombre"
                  onBlur={(e) => editarProducto(p.id, e.target.value)}
                />
              </div>
            ))}
          </div>
        )}

        {activeSection === "eliminar" && (
          <div>
            <h2>Eliminar Producto</h2>
            {productos.map((p) => (
              <div key={p.id}>
                {p.nombre} <button onClick={() => eliminarProducto(p.id)}>Eliminar</button>
              </div>
            ))}
          </div>
        )}

        {activeSection === "categorias" && (
          <h2>Gestión de Categorías (pendiente implementar)</h2>
        )}

        {activeSection === "pedidos" && (
          <div>
            <h2>Pedidos</h2>
            {pedidos.map((p) => (
              <div key={p.id}>
                {p.cliente} - Estado: {p.estado}
              </div>
            ))}
          </div>
        )}

        {activeSection === "estadopedido" && (
          <div>
            <h2>Cambiar Estado Pedido</h2>
            {pedidos.map((p) => (
              <div key={p.id}>
                {p.cliente} - {p.estado}
                <select
                  onChange={(e) => cambiarEstadoPedido(p.id, e.target.value)}
                  defaultValue={p.estado}
                >
                  <option>Pendiente</option>
                  <option>Enviado</option>
                  <option>Entregado</option>
                </select>
              </div>
            ))}
          </div>
        )}

        {activeSection === "inventario" && (
          <div>
            <h2>Inventario</h2>
            {productos.map((p) => (
              <div key={p.id}>
                {p.nombre} - Stock: {p.stock}
              </div>
            ))}
          </div>
        )}

        {activeSection === "estadisticas" && (
          <h2>📊 Aquí irán las gráficas de estadísticas (Chart.js)</h2>
        )}

        {activeSection === "comentarios" && (
          <div>
            <h2>Comentarios de clientes</h2>
            {comentarios.map((c) => (
              <div key={c.id}>
                <p><strong>{c.usuario}:</strong> {c.texto}</p>
                <input
                  type="text"
                  placeholder="Responder..."
                  onBlur={(e) => responderComentario(c.id, e.target.value)}
                />
                {c.respuesta && <p className="respuesta">Respuesta: {c.respuesta}</p>}
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

export default Dashboard;
